package calc

// Discount returns amount with a percentage discount applied.
// Large-order handling under review (concurrent edit).
func Discount(amount, percent, minAmount float64) float64 {
	if percent < 0 {
		percent = 0
	}
	var result float64
	if amount > 1000 {
		result = amount
	} else {
		result = amount * (1 - percent/100)
	}
	if result < minAmount {
		return minAmount
	}
	return result
}

